(3030, 1542, '_feedback_email', 'a:2:{s:2:\"to\";a:1:{i:0;s:40:\"samriddhi <samriddhi@zillioneconomy.com>\";}s:7:\"message\";s:4423:\"\n<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<style media=\"all\" type=\"text/css\">\n	body {\n		font-family: sans-serif;\n		-webkit-font-smoothing: antialiased;\n		font-size: 16px;\n		line-height: 1.3;\n		-ms-text-size-adjust: 100%;\n		-webkit-text-size-adjust: 100%;\n	}\n\n	table {\n		border-collapse: separate;\n		mso-table-lspace: 0pt;\n		mso-table-rspace: 0pt;\n		width: 100%;\n	}\n\n	table td {\n		font-family: Helvetica, sans-serif;\n		font-size: 16px;\n		vertical-align: top;\n	}\n\n	body {\n		background-color: #f6f7f7;\n		margin: 0;\n		padding: 0;\n	}\n\n	.body {\n		background-color: #f6f7f7;\n		width: 100%;\n	}\n\n	.container {\n		margin: 0 auto !important;\n		max-width: 640px;\n		padding: 0;\n		padding-top: 24px;\n		width: 640px;\n	}\n\n	.content {\n		box-sizing: border-box;\n		display: block;\n		margin: 0 auto;\n		max-width: 640px;\n		padding: 0;\n	}\n\n	.main {\n		background: #fff;\n		width: 100%;\n	}\n\n	.wrapper {\n		box-sizing: border-box;\n		padding: 24px;\n	}\n	.content-block {\n		box-sizing: border-box;\n		padding: 0 24px 24px;\n	}\n\n	.footer {\n		clear: both;\n		padding: 24px 0;\n		width: 100%;\n	}\n	.footer td,\n	.footer p,\n	.footer span,\n	.footer a {\n		color: #101517;\n		font-size: 12px;\n	}\n	h1 {\n		font-size: 20px;\n	}\n	p {\n		font-family: sans-serif;\n		font-size: 16px;\n		font-weight: normal;\n		margin: 0;\n		margin-bottom: 16px;\n	}\n\n	.powered-by a {\n		text-decoration: none;\n	}\n	@media only screen and (max-width: 640px) {\n		.main p,\n		.main td,\n		.main span {\n			font-size: 16px !important;\n		}\n		.wrapper {\n			padding: 8px 16px !important;\n		}\n		.powered-by {\n			padding: 0 16px 16px!important;\n		}\n		.content {\n			padding: 0 !important;\n		}\n		.container {\n			padding: 0 !important;\n			padding-top: