(64, 1, '2022-10-26 17:42:15', '2022-10-26 17:42:15', '<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"fse-study-lite\"} /-->\n\n<!-- wp:group {\"className\":\"hero-banner\",\"layout\":{\"inherit\":false}} -->\n<div class=\"wp-block-group hero-banner\"><!-- wp:cover {\"url\":\"https://zillioneconomy.com/wp-content/uploads/2022/10/StockSnap_M6D1GS9PSL.jpg\",\"id\":60,\"dimRatio\":50,\"isDark\":false,\"style\":{\"spacing\":{\"padding\":{\"top\":\"8em\",\"right\":\"1em\",\"bottom\":\"8em\",\"left\":\"1em\"}}}} -->\n<div class=\"wp-block-cover is-light\" style=\"padding-top:8em;padding-right:1em;padding-bottom:8em;padding-left:1em\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-60\" alt=\"\" src=\"https://zillioneconomy.com/wp-content/uploads/2022/10/StockSnap_M6D1GS9PSL.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"layout\":{\"inherit\":true}} -->\n<div class=\"wp-block-group\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"74%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:74%\"><!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"58px\"},\"spacing\":{\"margin\":{\"top\":\"0px\",\"right\":\"0px\",\"bottom\":\"20px\",\"left\":\"0px\"}}},\"textColor\":\"white\"} -->\n<h2 class=\"has-white-color has-text-color\" id=\"line1\" style=\"font-size:58px;margin-top:0px;margin-right:0px;margin-bottom:20px;margin-left:0px\"><strong>Anchored in Excellence.</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"white\"} -->\n<p class=\"has-white-color has-text-color\">Pellentesque bibendum non lorem ut dignissim. Etiam molestie ultrices enim, sit amet vehicula dui fermentum id. Ut fermentum augue ac varius venenatis. Nullam luctus pellentesque finibus. Cras eleifend purus iaculis, vulputate ex id, scelerisque quam.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"20px\"} -->\n<div style=\"height:20px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link\">Take a Tour</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"26%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:26%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"70px\",\"right\":\"15px\",\"bottom\":\"70px\",\"left\":\"15px\"}},\"color\":{\"background\":\"#fcfcfc\"}},\"layout\":{\"inherit\":false}} -->\n<div class=\"wp-block-group has-background\" style=\"background-color:#fcfcfc;padding-top:70px;padding-right:15px;padding-bottom:70px;padding-left:15px\"><!-- wp:group {\"layout\":{\"inherit\":true}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"space-between\"}} -->\n<div class=\"wp-block-group\"><!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:image {\"id\":1881,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"12px\"}}} -->\n<figure class=\"wp-block-image size-full\" style=\"border-radius:12px\"><img src=\"https://zillioneconomy.com/wp-content/themes/fse-study-lite/images/about.jpg\" alt=\"\" class=\"wp-image-1881\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"42px\"}},\"t