(122, 1, '2023-03-12 19:08:33', '2023-03-12 19:08:33', '<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"fse-study-lite\"} /-->\n\n<!-- wp:group {\"className\":\"hero-banner\",\"layout\":{\"inherit\":false}} -->\n<div class=\"wp-block-group hero-banner\"><!-- wp:cover {\"url\":\"https://zillioneconomy.com/wp-content/uploads/2022/10/StockSnap_M6D1GS9PSL.jpg\",\"id\":60,\"dimRatio\":50,\"isDark\":false,\"style\":{\"spacing\":{\"padding\":{\"top\":\"8em\",\"right\":\"1em\",\"bottom\":\"8em\",\"left\":\"1em\"}}}} -->\n<div class=\"wp-block-cover is-light\" style=\"padding-top:8em;padding-right:1em;padding-bottom:8em;padding-left:1em\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-60\" alt=\"\" src=\"https://zillioneconomy.com/wp-content/uploads/2022/10/StockSnap_M6D1GS9PSL.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"74%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:74%\"><!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"58px\"},\"spacing\":{\"margin\":{\"top\":\"0px\",\"right\":\"0px\",\"bottom\":\"20px\",\"left\":\"0px\"}}},\"textColor\":\"white\"} -->\n<h2 class=\"has-white-color has-text-color\" id=\"line1\" style=\"margin-top:0px;margin-right:0px;margin-bottom:20px;margin-left:0px;font-size:58px\">Explore the Zillion Economy</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"white\"} -->\n<p class=\"has-white-color has-text-color\">COFFEE, ECONOMICS, SLEEP, REPEAT.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"20px\"} -->\n<div style=\"height:20px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button /--></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"26%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:26%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"70px\",\"right\":\"15px\",\"bottom\":\"70px\",\"left\":\"15px\"}},\"color\":{\"background\":\"#fcfcfc\"}},\"layout\":{\"inherit\":false}} -->\n<div class=\"wp-block-group has-background\" style=\"background-color:#fcfcfc;padding-top:70px;padding-right:15px;padding-bottom:70px;padding-left:15px\"><!-- wp:group {\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"space-between\"}} -->\n<div class=\"wp-block-group\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"fontSize\":\"small\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center has-small-font-size\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:image {\"id\":1881,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"12px\"}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\"><img src=\"https://zillioneconomy.com/wp-content/themes/fse-study-lite/images/about.jpg\" alt=\"\" class=\"wp-image-1881\" style=\"border-radius:12px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"style\":{\"typography\":{\"textTransform\":\"none\"}},\"textColor\":\"black\",\"fontSize\":\"regular\"} -->\n<h2 class=\"has-black-color has-text-color has-regular-font-size\" style=\"text-transform:none\"><em>Are you ready to dive &amp; explore the sea  of economics?</em></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"black\"} -->\n<p class=\"has-black-color has-text-color\">Hey!!<br>I am Samriddhi Jadhav.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"black\"} -->\n<p class=\"has-black-color has-text-color\">At zillion economy , you will see the world through an economics lens. Hoping to share that lens with you all.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"black\"} -->\n<p class=\"has-black-color has-text-color\">The blogs are an overview of economic concepts , principles &amp; cover a variety of current economic issues &amp; topics related to Indian economy and the world economy. Eliminating all the layers that make economics difficult and boring. The content is super easy and understandable.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"black\",\"fontSize\":\"small\"} -->\n<p class=\"has-black-color has-text-color has-small-font-size\">I choose what I enjoy, I hope you will have some fun.<br>I have had the joy of spending thousands of hours under the sea of economics. I am taking you along to see what I see, and to know what I know.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"70px\",\"right\":\"15px\",\"bottom\":\"70px\",\"left\":\"15px\"}}},\"backgroundColor\":\"fse-study-lite-BlueGreen\"} -->\n<div class=\"wp-block-group has-fse-study-lite-blue-green-background-color has-background\" style=\"padding-top:70px;padding-right:15px;padding-bottom:70px;padding-left:15px\"><!-- wp:group {\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"42px\"},\"spacing\":{\"margin\":{\"top\":\"0px\",\"right\":\"0px\",\"bottom\":\"40px\",\"left\":\"0px\"}}},\"textColor\":\"fse-study-lite-DarkPink\"} -->\n<h2 class=\"has-text-align-center has-fse-study-lite-dark-pink-color has-text-color\" style=\"margin-top:0px;margin-right:0px;margin-bottom:40px;margin-left:0px;font-size:42px\">BLOGS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:query {\"queryId\":48,\"query\":{\"perPage\":6,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"exclude\",\"inherit\":false},\"displayLayout\":{\"type\":\"flex\",\"columns\":3}} -->\n<div class=\"wp-block-query\"><!-- wp:post-template -->\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0px\",\"right\":\"17px\",\"bottom\":\"24px\",\"left\":\"17px\"}},\"border\":{\"radius\":\"30px\",\"width\":\"2px\"}},\"backgroundColor\":\"fse-study-lite-DarkPink\",\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-group has-white-color has-fse-study-lite-dark-pink-background-color has-text-color has-background\" style=\"border-width:2px;border-radius:30px;padding-top:0px;padding-right:17px;padding-bottom:24px;padding-left:17px\"><!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:post-excerpt {\"moreText\":\"\",\"showMoreOnNewLine\":false,\"textColor\":\"white\"} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"space-between\"}} -->\n<div class=\"wp-block-group\"><!-- wp:post-date {\"format\":\"M j, Y\",\"displayType\":\"modified\",\"style\":{\"typography\":{\"fontSize\":\"14px\"}},\"textColor\":\"fse-study-lite-BlueGreen\"} /-->\n\n<!-- wp:post-author {\"showAvatar\":false,\"showBio\":false,\"byline\":\"BY\",\"style\":{\"typography\":{\"fontSize\":\"15px\"}},\"textColor\":\"fse-study-lite-BlueGreen\"} /--></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n<!-- /wp:post-template -->\n\n<!-- wp:spacer {\"height\":\"50px\"} -->\n<div style=\"height:50px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:query-pagination {\"paginationArrow\":\"chevron\",\"textColor\":\"fse-study-lite-DarkPink\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<!-- wp:query-pagination-previous /-->\n\n<!-- wp:query-pagination-numbers /-->\n\n<!-- wp:query-pagination-next /-->\n<!-- /wp:query-pagination --></div>\n<!-- /wp:query --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"has-text-align-center\"><strong><em><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-fse-study-lite-dark-pink-color\">LEARN MORE :</mark></em></strong></h1>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"ordered\":true,\"start\":1,\"textColor\":\"fse-study-lite-DarkPink\"} -->\n<ol start=\"1\" id=\"block-8f772de6-0900-42de-bec5-106bd8af7cb8\" class=\"has-fse-study-lite-dark-pink-color has-text-color\"><!-- wp:list-item -->\n<li>Global economic events that affect the international system.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Technology including the economic impact of new innovation.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Government policy and interventions, government involvement in the economy.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Market structures.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Global economic issues and its impact on India and the world economy.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"f